namespace SonrisaNews.Domain.Auth;

/// <summary>
/// String constants for every RBAC permission in the system. These are the
/// names used in <c>[Authorize(Policy = Permissions.X)]</c> attributes and
/// must match the <c>p</c> lines in <c>rbac_policy.csv</c>.
/// </summary>
/// <remarks>
/// Format: <c>&lt;Resource&gt;.&lt;Action&gt;.&lt;Scope&gt;</c>. The Casbin
/// adapter turns each name into a domain-specific check; the rbac-audit tool
/// treats these names as the source of truth for what code uses.
/// </remarks>
public static class Permissions
{
    public const string AlertsReadOwn = "Alerts.Read.Own";
    public const string AlertsWriteOwn = "Alerts.Write.Own";
    public const string AlertsReadAny = "Alerts.Read.Any";
    public const string AlertsWriteAny = "Alerts.Write.Any";

    public const string ChannelsReadOwn = "Channels.Read.Own";
    public const string ChannelsWriteOwn = "Channels.Write.Own";

    public const string SourcesReadAny = "Sources.Read.Any";
    public const string SourcesWriteAny = "Sources.Write.Any";

    public const string UsersReadAny = "Users.Read.Any";
    public const string UsersWriteAny = "Users.Write.Any";
    public const string UsersSuspend = "Users.Suspend";

    public const string AuditLogRead = "AuditLog.Read";
    public const string AnnouncementsWrite = "Announcements.Write";
    public const string HealthRead = "Health.Read";

    /// <summary>Background worker only. Not granted to a user-facing JWT.</summary>
    public const string MatcherRun = "Matcher.Run";

    /// <summary>Read-only view of the current user. Granted to every authenticated user.</summary>
    public const string ProfileRead = "Profile.Read";
}

namespace SonrisaNews.Domain.Auth;

/// <summary>
/// String constants for the three RBAC roles. Always use these in code rather
/// than inline strings — the rbac-audit tool and the CSV are the security
/// boundary, but the role name is referenced from multiple places and a
/// typo must not silently open up a permission.
/// </summary>
public static class Roles
{
    /// <summary>Default. Can manage own alerts, channels, profile.</summary>
    public const string User = "User";

    /// <summary>Can manage data sources, users, announcements, system health. Audit-logged on every action.</summary>
    public const string Admin = "Admin";

    /// <summary>Internal role for background workers. Cannot sign in.</summary>
    public const string System = "System";
}

namespace SonrisaNews.Domain.Auth;

/// <summary>
/// Marker for the authorization requirement resolved by
/// <c>RbacPolicyHandler</c>. The string payload is the permission name (one
/// of the constants in <see cref="Permissions"/>).
/// </summary>
/// <remarks>
/// ASP.NET Core's authorization system needs a class implementing
/// <c>IAuthorizationRequirement</c> to be associated with a policy via
/// <c>AddPolicy(name, policy =&gt; policy.Requirements.Add(new PermissionRequirement(name)))</c>.
/// The Casbin handler reads the requirement's <see cref="Permission"/> and
/// asks the enforcer whether the current user has it.
/// </remarks>
public sealed class PermissionRequirement(string permission) : Microsoft.AspNetCore.Authorization.IAuthorizationRequirement
{
    public string Permission { get; } = permission;
}

using Casbin.NET.Persist;
using Casbin.NET.Persist.File;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain.Auth;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Casbin-backed authorization handler. Resolves
/// <see cref="PermissionRequirement"/> by asking the enforcer whether the
/// current user (sub) is allowed to perform the action (act) on the resource
/// (obj). The handler is the <em>only</em> authorization enforcement point;
/// controllers do not re-check ownership.
/// </summary>
/// <remarks>
/// <para>
/// Resource ownership ("can this user act on their own alert?") is enforced
/// by the policy <c>p</c> line having a <c>.Own</c> scope and the controller
/// passing the resource owner id as <c>obj</c>. For example, a user
/// requesting <c>GET /alerts/&lt;alertId&gt;</c> passes <c>obj = alertId</c>;
/// the policy grants <c>User -&gt; Alerts.Read.Own -&gt; access</c>, and the
/// Casbin matcher uses <c>keyMatch</c> on the <c>.Own</c> suffix. The
/// database ownership check happens separately in the service layer — the
/// RBAC handler is coarse-grained ("can this role perform this action on
/// the resource class?"), the service is fine-grained ("does the resource
/// belong to the caller?").
/// </para>
/// <para>
/// For the matcher / dispatcher (background work, waves 6–8), the request
/// has no HttpContext claims. The dispatcher constructs a synthetic
/// <c>ICurrentUser</c> with <c>Role = System</c> — a future wave adds a
/// <c>SystemContextMiddleware</c> or a per-worker service-provider shim.
/// For now, the handler returns 403 if no <see cref="ICurrentUser"/> is
/// bound to the call.
/// </para>
/// </remarks>
public sealed class RbacPolicyHandler(
    ICurrentUser currentUser,
    IEnforcerBootstrap enforcerBootstrap,
    ILogger<RbacPolicyHandler> logger) : AuthorizationHandler<PermissionRequirement>
{
    /// <inheritdoc />
    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        if (currentUser.Id is null)
        {
            // No identity bound — the [Authorize] attribute should never
            // allow an unauthenticated request through, but the
            // [AllowAnonymous] path or a misconfigured policy might. The
            // 403 here is the safe default; the JwtBearer middleware sets
            // 401 when the token is missing/invalid, so by the time we get
            // here, a missing user means a misconfiguration.
            logger.LogWarning(
                "RBAC handler saw no current user for permission {Permission}; denying.",
                requirement.Permission);
            return;
        }

        // The Casbin sub is the user's email (stable across renames);
        // grouping is kept in sync with the User.Role column by
        // RoleGroupingService.
        var enforcer = await enforcerBootstrap.GetEnforcerAsync(context.User.Identity?.AuthenticationType);
        var allowed = await enforcer.EnforceAsync(
            sub: currentUser.Email,
            obj: requirement.Permission,
            act: "access");

        if (!allowed)
        {
            logger.LogWarning(
                "RBAC denied for user {UserId} on {Permission}",
                currentUser.Id,
                requirement.Permission);
            return;
        }

        context.Succeed(requirement);
    }
}

