using System.Security.Claims;
using Microsoft.AspNetCore.Http;
using SonrisaNews.Domain.Entities;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// The current request's authenticated user. Backed by the JWT claims set
/// populated by <c>JwtBearer</c> middleware. The auth flow writes the user's
/// id (sub), email, and role into the token; this abstraction surfaces them
/// to controllers and the RBAC handler.
/// </summary>
public interface ICurrentUser
{
    /// <summary>The user's id, or <c>null</c> if the request is unauthenticated.</summary>
    Guid? Id { get; }

    /// <summary>The user's email, or <c>null</c> if the request is unauthenticated.</summary>
    string? Email { get; }

    /// <summary>The user's role as the <see cref="UserRole"/> enum value, or <c>null</c> if unauthenticated.</summary>
    UserRole? Role { get; }

    /// <summary>True if the request has a valid JWT.</summary>
    bool IsAuthenticated { get; }
}

/// <summary>
/// <see cref="ICurrentUser"/> implementation backed by <see cref="IHttpContextAccessor"/>.
/// The JWT bearer middleware is responsible for turning the bearer token into
/// claims; we just read them here.
/// </summary>
public sealed class HttpContextCurrentUser(IHttpContextAccessor httpContextAccessor) : ICurrentUser
{
    private const string IdClaimType = ClaimTypes.NameIdentifier;
    private const string EmailClaimType = ClaimTypes.Email;
    private const string RoleClaimType = ClaimTypes.Role;

    public bool IsAuthenticated => httpContextAccessor.HttpContext?.User?.Identity?.IsAuthenticated == true;

    public Guid? Id
    {
        get
        {
            var raw = FindClaim(IdClaimType);
            return Guid.TryParse(raw, out var id) ? id : null;
        }
    }

    public string? Email => FindClaim(EmailClaimType);

    public UserRole? Role
    {
        get
        {
            var raw = FindClaim(RoleClaimType);
            return Enum.TryParse<UserRole>(raw, ignoreCase: true, out var role) ? role : null;
        }
    }

    private string? FindClaim(string type)
    {
        var user = httpContextAccessor.HttpContext?.User;
        if (user is null || !user.Identity?.IsAuthenticated == true) return null;
        return user.FindFirst(type)?.Value;
    }
}

using Casbin;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain.Auth;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Resolves the <see cref="IEnforcer"/> instance for the running host. The
/// enforcer is created once at startup from the model and CSV files
/// shipped under <c>Auth/</c> in the Infrastructure project, and shared by
/// all RBAC handlers. Role groupings are added in memory at runtime by
/// <see cref="RoleGroupingService"/>; the enforcer is then asked to rebuild
/// its role links.
/// </summary>
public interface IEnforcerBootstrap
{
    /// <summary>
    /// Returns the shared enforcer. The first call resolves the file paths
    /// and loads the policy; subsequent calls return the cached instance.
    /// </summary>
    /// <param name="authenticationScheme">Optional. Not used by the default
    /// in-process enforcer, but reserved for the future per-scheme adapter
    /// (e.g. the matcher worker using a <c>System</c> identity).</param>
    Task<IEnforcer> GetEnforcerAsync(string? authenticationScheme = null);
}

/// <summary>
/// File-backed enforcer bootstrap. Resolves <c>casbin_model.conf</c> and
/// <c>rbac_policy.csv</c> relative to the running host's content root so
/// the same code path works for the dev process, the AppHost, and the
/// integration-test <c>WebApplicationFactory</c>.
/// </summary>
/// <remarks>
/// The enforcer is built with <c>AutoBuildRoleLinks = true</c> so
/// <c>AddNamedGroupingPolicy</c> calls from <see cref="RoleGroupingService"/>
/// immediately affect the next <c>EnforceAsync</c> call.
/// </remarks>
public sealed class FileEnforcerBootstrap(
    IWebHostEnvironment environment,
    ILogger<FileEnforcerBootstrap> logger) : IEnforcerBootstrap
{
    private const string ModelRelativePath = "Auth/casbin_model.conf";
    private const string PolicyRelativePath = "Auth/rbac_policy.csv";

    private readonly SemaphoreSlim _gate = new(1, 1);
    private IEnforcer? _enforcer;
    private string? _resolvedPolicyPath;

    public async Task<IEnforcer> GetEnforcerAsync(string? authenticationScheme = null)
    {
        if (_enforcer is not null) return _enforcer;

        await _gate.WaitAsync();
        try
        {
            if (_enforcer is not null) return _enforcer;

            var modelPath = Path.Combine(environment.ContentRootPath, ModelRelativePath);
            var policyPath = Path.Combine(environment.ContentRootPath, PolicyRelativePath);

            if (!File.Exists(modelPath))
            {
                throw new InvalidOperationException(
                    $"RBAC model not found at {modelPath}. " +
                    "The Infrastructure project must copy Auth/casbin_model.conf to the output directory.");
            }
            if (!File.Exists(policyPath))
            {
                throw new InvalidOperationException(
                    $"RBAC policy not found at {policyPath}. " +
                    "The Infrastructure project must copy Auth/rbac_policy.csv to the output directory.");
            }

            _resolvedPolicyPath = policyPath;

            logger.LogInformation("Loading RBAC enforcer from {ModelPath} + {PolicyPath}", modelPath, policyPath);
            _enforcer = await Enforcer.CreateAsync(modelPath, policyPath);
            _enforcer.AutoBuildRoleLinks = true;
            return _enforcer;
        }
        finally
        {
            _gate.Release();
        }
    }

    /// <summary>The absolute path of the loaded policy file. For diagnostics.</summary>
    public string? ResolvedPolicyPath => _resolvedPolicyPath;
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain.Auth;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Casbin-backed authorization handler. Resolves
/// <see cref="PermissionRequirement"/> by asking the enforcer whether the
/// current user (sub) is allowed to perform the action (act) on the
/// resource (obj).
/// </summary>
/// <remarks>
/// <para>
/// The handler is the <em>only</em> authorization enforcement point;
/// controllers do not re-check ownership. Resource ownership is encoded in
/// the policy's <c>.Own</c> suffix (e.g. <c>Alerts.Read.Own</c>) and the
/// Casbin matcher uses <c>keyMatch</c> on the resource name. Fine-grained
/// ownership ("does this alert actually belong to the caller?") is the
/// service layer's job — the RBAC handler is coarse-grained ("can this
/// role perform this action on the resource class at all?").
/// </para>
/// <para>
/// For the matcher / dispatcher (background work, waves 6–8), the request
/// has no HttpContext claims. A future wave adds a
/// <c>SystemContextMiddleware</c> or a per-worker service-provider shim
/// that binds an <see cref="ICurrentUser"/> with <c>Role = System</c>. For
/// now, the handler returns 403 if no current user is bound.
/// </para>
/// </remarks>
public sealed class RbacPolicyHandler(
    ICurrentUser currentUser,
    IEnforcerBootstrap enforcerBootstrap,
    ILogger<RbacPolicyHandler> logger) : AuthorizationHandler<PermissionRequirement>
{
    /// <inheritdoc />
    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        if (currentUser.Id is null)
        {
            // No identity bound — the [Authorize] attribute should never
            // allow an unauthenticated request through (the JwtBearer
            // middleware returns 401 when the token is missing), so by the
            // time we get here, a missing user means a misconfiguration.
            logger.LogWarning(
                "RBAC handler saw no current user for permission {Permission}; denying.",
                requirement.Permission);
            return;
        }

        // The Casbin sub is the user's email (stable across renames);
        // grouping is kept in sync with the User.Role column by
        // RoleGroupingService.
        var enforcer = await enforcerBootstrap.GetEnforcerAsync(context.User.Identity?.AuthenticationType);
        var allowed = await enforcer.EnforceAsync(
            EnforceContext.Empty,
            new EnforceRequest(
                Sub: currentUser.Email ?? string.Empty,
                Obj: requirement.Permission,
                Act: "access"));

        if (!allowed)
        {
            logger.LogWarning(
                "RBAC denied for user {UserId} on {Permission}",
                currentUser.Id,
                requirement.Permission);
            return;
        }

        context.Succeed(requirement);
    }
}

/// <summary>The three-field request shape used by <c>casbin_model.conf</c>.</summary>
/// <param name="Sub">The subject (user email).</param>
/// <param name="Obj">The object / resource (permission name).</param>
/// <param name="Act">The action (always <c>access</c> in this codebase).</param>
public sealed record EnforceRequest(string Sub, string Obj, string Act);

