using Casbin;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Persistence;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Keeps the Casbin enforcer's <c>g</c> (grouping) lines in sync with the
/// <see cref="User.Role"/> column. Without this sync, the <c>p</c> lines in
/// <c>rbac_policy.csv</c> would only know about the bootstrap admin; every
/// other user's role would be invisible to the enforcer.
/// </summary>
/// <remarks>
/// <para>
/// The default mode is <see cref="GroupingMode.Lazy"/>: the in-memory enforcer
/// is hydrated once at startup with every existing <c>User</c> row, and the
/// service adds / removes groupings on demand as users are created, updated,
/// or deleted. Wave 5+ (Alert CRUD) calls
/// <see cref="EnsureGroupingAsync"/> from the auth flow on user create /
/// update / role-change.
/// </para>
/// <para>
/// For the background worker (waves 6–8), the dispatcher's
/// <see cref="ICurrentUser"/> carries <c>Role = System</c> and the enforcer
/// is asked about <c>Matcher.Run</c>. This is a policy check, not a
/// grouping, so it doesn't need <see cref="EnsureGroupingAsync"/>.
/// </para>
/// </remarks>
public interface IRoleGroupingService
{
    /// <summary>
    /// Ensures the in-memory enforcer knows that <paramref name="user"/> has
    /// <paramref name="role"/>. Idempotent — re-asserts the same role is a
    /// no-op, switching from <c>User</c> to <c>Admin</c> removes the old
    /// grouping and adds the new one.
    /// </summary>
    Task EnsureGroupingAsync(User user, UserRole role, CancellationToken ct = default);

    /// <summary>Removes all groupings for the given user. Idempotent.</summary>
    Task RemoveGroupingAsync(string userEmail, CancellationToken ct = default);
}

public sealed class RoleGroupingService(
    IEnforcerBootstrap enforcerBootstrap,
    IDbContextFactory<SonrisaNewsDbContext> dbContextFactory,
    ILogger<RoleGroupingService> logger) : IRoleGroupingService
{
    private static readonly IReadOnlyDictionary<UserRole, string> RoleToCasbinRole = new Dictionary<UserRole, string>
    {
        [UserRole.User] = SonrisaNews.Domain.Auth.Roles.User,
        [UserRole.Admin] = SonrisaNews.Domain.Auth.Roles.Admin,
        // System users are not subject to the RBAC handler — they go through
        // a different seam in the worker. The CSV still grants p, System,
        // Matcher.Run so an admin can audit the system role if needed.
    };

    public async Task EnsureGroupingAsync(User user, UserRole role, CancellationToken ct = default)
    {
        if (!RoleToCasbinRole.TryGetValue(role, out var casbinRole)) return;
        var enforcer = await enforcerBootstrap.GetEnforcerAsync();

        // Drop any prior role for this user, then add the new one. The
        // enforcer's grouped-policies list is small (one entry per user);
        // the brute-force "remove all then add one" approach is correct
        // and clear, and avoids relying on the enforcer's role-history.
        var existing = await GetCurrentRolesForUserAsync(enforcer, user.Email, ct);
        foreach (var oldRole in existing)
        {
            await enforcer.RemoveNamedGroupingPolicyAsync("g", user.Email, oldRole);
        }
        await enforcer.AddNamedGroupingPolicyAsync("g", user.Email, casbinRole);
        logger.LogInformation("RBAC grouping: {Email} -> {Role}", user.Email, casbinRole);
    }

    public async Task RemoveGroupingAsync(string userEmail, CancellationToken ct = default)
    {
        var enforcer = await enforcerBootstrap.GetEnforcerAsync();
        var existing = await GetCurrentRolesForUserAsync(enforcer, userEmail, ct);
        foreach (var oldRole in existing)
        {
            await enforcer.RemoveNamedGroupingPolicyAsync("g", userEmail, oldRole);
        }
    }

    private static async Task<IReadOnlyList<string>> GetCurrentRolesForUserAsync(
        IEnforcer enforcer, string userEmail, CancellationToken ct)
    {
        // The Casbin.NET API surfaces role lookups through the typed-roles
        // helpers on the enforcer. We pull the list and let the caller
        // decide what to do with it.
        ct.ThrowIfCancellationRequested();
        var roles = await enforcer.GetRolesForUserAsync(userEmail);
        return roles;
    }
}

