using Casbin;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Auth;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Persistence;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Keeps the Casbin enforcer's <c>g</c> (grouping) lines in sync with the
/// <see cref="User.Role"/> column. Without this sync, the <c>p</c> lines in
/// <c>rbac_policy.csv</c> would only know about the bootstrap admin; every
/// other user's role would be invisible to the enforcer.
/// </summary>
/// <remarks>
/// <para>
/// The service is invoked from the auth flow on user create, role change,
/// and user delete. The Casbin grouping is global to the enforcer instance
/// (one per app); multiple API instances must share the same enforcer
/// state. For wave 3 (single API process) the in-memory model is correct;
/// the wave 8 cleanup pass is a good place to revisit when the worker
/// also needs to ask "can this user do X?" without a JWT.
/// </para>
/// <para>
/// For the background worker (waves 6–8), the dispatcher's
/// <see cref="ICurrentUser"/> carries <c>Role = System</c> and the enforcer
/// is asked about <c>Matcher.Run</c>. This is a policy check, not a
/// grouping, so it doesn't need <see cref="EnsureGroupingAsync"/>.
/// </para>
/// </remarks>
public interface IRoleGroupingService
{
    /// <summary>
    /// Ensures the in-memory enforcer knows that the user has the given
    /// role. Idempotent — re-asserting the same role is a no-op, switching
    /// from <c>User</c> to <c>Admin</c> removes the old grouping and adds
    /// the new one.
    /// </summary>
    Task EnsureGroupingAsync(string userEmail, UserRole role, CancellationToken ct = default);

    /// <summary>Removes all groupings for the given user. Idempotent.</summary>
    Task RemoveGroupingAsync(string userEmail, CancellationToken ct = default);

    /// <summary>Hydrates the in-memory enforcer with all existing users' roles. Called at startup.</summary>
    Task HydrateAsync(CancellationToken ct = default);
}

public sealed class RoleGroupingService(
    IEnforcerBootstrap enforcerBootstrap,
    IDbContextFactory<SonrisaNewsDbContext> dbContextFactory,
    ILogger<RoleGroupingService> logger) : IRoleGroupingService
{
    /// <summary>Default domain in our flat model. Casbin supports per-domain grouping; we don't use it in MVP.</summary>
    private const string DefaultDomain = "";

    private static readonly IReadOnlyDictionary<UserRole, string> RoleToCasbinRole = new Dictionary<UserRole, string>
    {
        [UserRole.User] = Roles.User,
        [UserRole.Admin] = Roles.Admin,
        // System users are not subject to the RBAC handler — they go through
        // a different seam in the worker. The CSV still grants p, System,
        // Matcher.Run so an admin can audit the system role if needed.
    };

    public async Task EnsureGroupingAsync(string userEmail, UserRole role, CancellationToken ct = default)
    {
        if (!RoleToCasbinRole.TryGetValue(role, out var casbinRole)) return;
        var enforcer = await enforcerBootstrap.GetEnforcerAsync();

        // Drop any prior role for this user, then add the new one. The
        // enforcer's grouped-policies list is small (one entry per user);
        // the brute-force "remove all then add one" approach is correct
        // and clear, and avoids relying on the enforcer's role-history.
        var existing = RbacEnforcerExtension.GetRolesForUser(enforcer, userEmail, DefaultDomain);
        foreach (var oldRole in existing)
        {
            await RbacEnforcerExtension.DeleteRoleForUserAsync(enforcer, userEmail, oldRole, DefaultDomain);
        }
        await RbacEnforcerExtension.AddRoleForUserAsync(enforcer, userEmail, casbinRole, DefaultDomain);
        logger.LogInformation("RBAC grouping: {Email} -> {Role}", userEmail, casbinRole);
    }

    public async Task RemoveGroupingAsync(string userEmail, CancellationToken ct = default)
    {
        var enforcer = await enforcerBootstrap.GetEnforcerAsync();
        await RbacEnforcerExtension.DeleteRolesForUserAsync(enforcer, userEmail, DefaultDomain);
    }

    public async Task HydrateAsync(CancellationToken ct = default)
    {
        // The API calls this once at startup so the enforcer knows every
        // pre-existing user's role. New signups go through EnsureGroupingAsync
        // from AuthService. The user list is bounded (O(hundreds) at MVP);
        // a streaming rehydrate is unnecessary.
        await using var db = await dbContextFactory.CreateDbContextAsync(ct);
        var users = await db.Users.AsNoTracking()
            .Where(u => u.Role != UserRole.System)
            .Select(u => new { u.Email, u.Role })
            .ToListAsync(ct);

        var enforcer = await enforcerBootstrap.GetEnforcerAsync();
        foreach (var u in users)
        {
            if (!RoleToCasbinRole.TryGetValue(u.Role, out var casbinRole)) continue;
            await RbacEnforcerExtension.AddRoleForUserAsync(enforcer, u.Email, casbinRole, DefaultDomain);
        }
        logger.LogInformation("RBAC hydrate: {Count} users loaded", users.Count);
    }
}

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Hashes and verifies passwords. The default implementation uses BCrypt
/// with a work factor of 12 (the same value the <c>seed-admin-user</c> skill
/// uses), so the seed and the auth flow agree on the algorithm.
/// </summary>
public interface IPasswordHasher
{
    /// <summary>Hashes a plaintext password. Returns the encoded PHC string.</summary>
    string Hash(string plaintext);

    /// <summary>Verifies a plaintext password against a previously hashed value.</summary>
    /// <returns><c>true</c> if the password matches the hash; <c>false</c> otherwise.</returns>
    bool Verify(string plaintext, string hash);
}

/// <summary>BCrypt-backed <see cref="IPasswordHasher"/>. Work factor 12 (~250ms on a 2026-era server).</summary>
public sealed class BCryptPasswordHasher : IPasswordHasher
{
    /// <summary>BCrypt work factor. 12 is the standard for 2026 — 10 is the minimum recommended, 14 is overkill for web auth.</summary>
    private const int WorkFactor = 12;

    public string Hash(string plaintext) => BCrypt.Net.BCrypt.HashPassword(plaintext, WorkFactor);

    public bool Verify(string plaintext, string hash)
    {
        try
        {
            return BCrypt.Net.BCrypt.Verify(plaintext, hash);
        }
        catch (BCrypt.Net.SaltParseException)
        {
            // The hash column had an old / corrupt value (e.g. an empty
            // string from a half-applied migration). Treat as "no match"
            // rather than 500-ing on a typo in a historical row.
            return false;
        }
    }
}

using System.Security.Cryptography;
using System.Text;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// One-way hash for short-lived, single-use tokens (email-verification,
/// password-reset, magic links). SHA-256 is appropriate here because the
/// tokens are high-entropy random values (see <see cref="GenerateOpaqueToken"/>)
/// and have a short lifetime (24h). Argon2id would slow down the legitimate
/// use case for no security gain.
/// </summary>
public interface ITokenHasher
{
    /// <summary>Hashes a token. Returns a lowercase hex string (64 chars for SHA-256).</summary>
    string Hash(string token);

    /// <summary>Generates a cryptographically random opaque token (32 bytes → 64 hex chars or 43 base64url chars).</summary>
    string GenerateOpaqueToken();
}

/// <summary>SHA-256-backed <see cref="ITokenHasher"/>.</summary>
public sealed class Sha256TokenHasher : ITokenHasher
{
    public string Hash(string token)
    {
        ArgumentException.ThrowIfNullOrEmpty(token);
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(token));
        return Convert.ToHexString(bytes).ToLowerInvariant();
    }

    public string GenerateOpaqueToken()
    {
        // 32 bytes (256 bits) of random data, base64url-encoded. Matches
        // the entropy budget of a SHA-256 hash output.
        var bytes = RandomNumberGenerator.GetBytes(32);
        return Convert.ToBase64String(bytes)
            .Replace('+', '-')
            .Replace('/', '_')
            .TrimEnd('=');
    }
}

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Sends transactional email. The MVP default is a no-op
/// <c>LoggingEmailSender</c> (writes the body to a structured log line);
/// a real SMTP implementation lands in wave 4 alongside the channel
/// abstraction. Tests use a fake to capture sent messages.
/// </summary>
public interface IEmailSender
{
    /// <summary>Send a single message. Implementations must throw on permanent failures (bad address) and return normally on transient ones (timeouts).</summary>
    /// <param name="to">Recipient email address.</param>
    /// <param name="subject">Plain-text subject.</param>
    /// <param name="body">Plain-text body. HTML is wave 9 (React Email).</param>
    /// <param name="ct">Cancellation token.</param>
    Task SendAsync(string to, string subject, string body, CancellationToken ct = default);
}

/// <summary>Logs the email payload instead of sending it. Use in dev when no SMTP is configured.</summary>
public sealed class LoggingEmailSender(ILogger<LoggingEmailSender> logger) : IEmailSender
{
    public Task SendAsync(string to, string subject, string body, CancellationToken ct = default)
    {
        // Structured properties, no PII in the subject/body — just the
        // recipient address (which is the PII, but it's also necessary to
        // verify the email was routed correctly).
        logger.LogInformation(
            "Email (dev): to={To} subject={Subject} bodyChars={BodyLength}",
            to, subject, body.Length);
        return Task.CompletedTask;
    }
}

