using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain.Auth;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Casbin-backed authorization handler. Resolves
/// <see cref="PermissionRequirement"/> by asking the enforcer whether the
/// current user (sub) is allowed to perform the action (act) on the resource
/// (obj). The handler is the <em>only</em> authorization enforcement point;
/// controllers do not re-check ownership.
/// </summary>
/// <remarks>
/// <para>
/// Resource ownership ("can this user act on their own alert?") is enforced
/// by the policy <c>p</c> line having a <c>.Own</c> scope and the controller
/// passing the resource owner id as <c>obj</c>. For example, a user
/// requesting <c>GET /alerts/&lt;alertId&gt;</c> passes <c>obj = alertId</c>;
/// the policy grants <c>User -&gt; Alerts.Read.Own -&gt; access</c>, and the
/// Casbin matcher uses <c>keyMatch</c> on the <c>.Own</c> suffix. The
/// database ownership check happens separately in the service layer — the
/// RBAC handler is coarse-grained ("can this role perform this action on
/// the resource class?"), the service is fine-grained ("does the resource
/// belong to the caller?").
/// </para>
/// <para>
/// For the matcher / dispatcher (background work, waves 6–8), the request
