public sealed class RbacPolicyHandler(
    ICurrentUser currentUser,
    IEnforcerBootstrap enforcerBootstrap,
    ILogger<RbacPolicyHandler> logger) : AuthorizationHandler<PermissionRequirement>
{
    /// <inheritdoc />
    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        if (currentUser.Id is null)
        {
            // No identity bound — the [Authorize] attribute should never
            // allow an unauthenticated request through, but the
            // [AllowAnonymous] path or a misconfigured policy might. The
            // 403 here is the safe default; the JwtBearer middleware sets
            // 401 when the token is missing/invalid, so by the time we get
            // here, a missing user means a misconfiguration.
            logger.LogWarning(
                "RBAC handler saw no current user for permission {Permission}; denying.",
                requirement.Permission);
            return;
        }

        // The Casbin sub is the user's email (stable across renames);
        // grouping is kept in sync with the User.Role column by
        // RoleGroupingService.
        var enforcer = await enforcerBootstrap.GetEnforcerAsync(context.User.Identity?.AuthenticationType);
        var allowed = await enforcer.EnforceAsync(
            sub: currentUser.Email,
            obj: requirement.Permission,
            act: "access");

        if (!allowed)
        {
            logger.LogWarning(
                "RBAC denied for user {UserId} on {Permission}",
                currentUser.Id,
                requirement.Permission);
            return;
        }

        context.Succeed(requirement);
    }
}
