{"content":"using System.Security.Claims;
using Microsoft.AspNetCore.Http;
using SonrisaNews.Domain.Entities;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// The current request's authenticated user. Backed by the JWT claims set
/// populated by <c>JwtBearer</c> middleware. The auth flow writes the user's
/// id (sub), email, and role into the token; this abstraction surfaces them
/// to controllers and the RBAC handler.
/// </summary>
public interface ICurrentUser
{
    /// <summary>The user's id, or <c>null</c> if the request is unauthenticated.</summary>
    Guid? Id { get; }

    /// <summary>The user's email, or <c>null</c> if the request is unauthenticated.</summary>
    string? Email { get; }

    /// <summary>The user's role as the <see cref="UserRole"/> enum value, or <c>null</c> if unauthenticated.</summary>
    UserRole? Role { get; }

    /// <summary>True if the request has a valid JWT.</summary>
    bool IsAuthenticated { get; }
}

/// <summary>
/// <see cref="ICurrentUser"/> implementation backed by <see cref="IHttpContextAccessor"/>.
/// The JWT bearer middleware is responsible for turning the bearer token into
/// claims; we just read them here.
/// </summary>
public sealed class HttpContextCurrentUser(IHttpContextAccessor httpContextAccessor) : ICurrentUser
{
    private const string IdClaimType = ClaimTypes.NameIdentifier;
    private const string EmailClaimType = ClaimTypes.Email;
    private const string RoleClaimType = ClaimTypes.Role;

    public bool IsAuthenticated => httpContextAccessor.HttpContext?.User?.Identity?.IsAuthenticated == true;

    public Guid? Id
    {
        get
        {
            var raw = FindClaim(IdClaimType);
            return Guid.TryParse(raw, out var id) ? id : null;
        }
    }

    public string? Email => FindClaim(EmailClaimType);

    public UserRole? Role
    {
        get
        {
            var raw = FindClaim(RoleClaimType);
            return Enum.TryParse<UserRole>(raw, ignoreCase: true, out var role) ? role : null;
        }
    }

    private string? FindClaim(string type)
    {
        var user = httpContextAccessor.HttpContext?.User;
        if (user is null || !user.Identity?.IsAuthenticated == true) return null;
        return user.FindFirst(type)?.Value;
    }
}
