{"content":"using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using SonrisaNews.Domain.Auth;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Casbin-backed authorization handler. Resolves
/// <see cref="PermissionRequirement"/> by asking the enforcer whether the
/// current user (sub) is allowed to perform the action (act) on the
/// resource (obj).
/// </summary>
/// <remarks>
/// <para>
/// The handler is the <em>only</em> authorization enforcement point;
/// controllers do not re-check ownership. Resource ownership is encoded in
/// the policy's <c>.Own</c> suffix (e.g. <c>Alerts.Read.Own</c>) and the
/// Casbin matcher uses <c>keyMatch</c> on the resource name. Fine-grained
/// ownership ("does this alert actually belong to the caller?") is the
/// service layer's job — the RBAC handler is coarse-grained ("can this
/// role perform this action on the resource class at all?").
/// </para>
/// <para>
/// For the matcher / dispatcher (background work, waves 6–8), the request
/// has no HttpContext claims. A future wave adds a
/// <c>SystemContextMiddleware</c> or a per-worker service-provider shim
/// that binds an <see cref="ICurrentUser"/> with <c>Role = System</c>. For
/// now, the handler returns 403 if no current user is bound.
/// </para>
/// </remarks>
public sealed class RbacPolicyHandler(
    ICurrentUser currentUser,
    IEnforcerBootstrap enforcerBootstrap,
    ILogger<RbacPolicyHandler> logger) : AuthorizationHandler<PermissionRequirement>
{
    /// <inheritdoc />
    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        if (currentUser.Id is null)
        {
            // No identity bound — the [Authorize] attribute should never
            // allow an unauthenticated request through (the JwtBearer
            // middleware returns 401 when the token is missing), so by the
            // time we get here, a missing user means a misconfiguration.
            logger.LogWarning(
                "RBAC handler saw no current user for permission {Permission}; denying.",
                requirement.Permission);
            return;
        }

        // The Casbin sub is the user's email (stable across renames);
        // grouping is kept in sync with the User.Role column by
        // RoleGroupingService.
        var enforcer = await enforcerBootstrap.GetEnforcerAsync(context.User.Identity?.AuthenticationType);
        var allowed = await enforcer.EnforceAsync(
            EnforceContext.Empty,
            new EnforceRequest(
                Sub: currentUser.Email ?? string.Empty,
                Obj: requirement.Permission,
                Act: "access"));

        if (!allowed)
        {
            logger.LogWarning(
                "RBAC denied for user {UserId} on {Permission}",
                currentUser.Id,
                requirement.Permission);
            return;
        }

        context.Succeed(requirement);
    }
}

/// <summary>The three-field request shape used by <c>casbin_model.conf</c>.</summary>
/// <param name="Sub">The subject (user email).</param>
/// <param name="Obj">The object / resource (permission name).</param>
/// <param name="Act">The action (always <c>access</c> in this codebase).</param>
public sealed record EnforceRequest(string Sub, string Obj, string Act);
