{"content":"using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Casbin;
using FluentAssertions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Authorization.Infrastructure;
using Microsoft.Extensions.Logging.Abstractions;
using SonrisaNews.Domain.Auth;
using SonrisaNews.Infrastructure.Auth;
using Xunit;

namespace SonrisaNews.UnitTests.Auth;

/// <summary>
/// The RBAC + auth tripwire (per <c>rbac-policies.instructions.md</c>):
/// every change to <c>Auth/</c> or <c>rbac_policy.csv</c> ships with a
/// positive and a negative test. These tests are the canonical example.
/// </summary>
public class RbacPolicyHandlerTests
{
    [Fact]
    public async Task Admin_CanSuspendUsers_AllowedByPolicy()
    {
        // Positive: an admin (alice) is allowed to do Users.Suspend.
        var handler = NewHandler("alice@example.com", Roles.Admin);
        var requirement = new PermissionRequirement(Permissions.UsersSuspend);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal("alice@example.com"), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeTrue("Admin must be granted Users.Suspend in rbac_policy.csv");
    }

    [Fact]
    public async Task RegularUser_CannotSuspendUsers_RejectedByPolicy()
    {
        // Negative: a regular user (bob) is NOT allowed to do Users.Suspend.
        var handler = NewHandler("bob@example.com", Roles.User);
        var requirement = new PermissionRequirement(Permissions.UsersSuspend);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal("bob@example.com"), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeFalse("User must NOT be granted Users.Suspend — only Admin is");
    }

    [Fact]
    public async Task User_CanReadOwnAlerts_AllowedByPolicy()
    {
        // Positive: a regular user is allowed to do Alerts.Read.Own.
        var handler = NewHandler("bob@example.com", Roles.User);
        var requirement = new PermissionRequirement(Permissions.AlertsReadOwn);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal("bob@example.com"), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeTrue("User must be granted Alerts.Read.Own in rbac_policy.csv");
    }

    [Fact]
    public async Task User_CannotManageSources_RejectedByPolicy()
    {
        // Negative: a regular user is NOT allowed to do Sources.Write.Any.
        var handler = NewHandler("bob@example.com", Roles.User);
        var requirement = new PermissionRequirement(Permissions.SourcesWriteAny);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal("bob@example.com"), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeFalse("User must NOT be granted Sources.Write.Any — only Admin is");
    }

    [Fact]
    public async Task System_CanRunMatcher_AllowedByPolicy()
    {
        // Positive: a System caller (background worker) is allowed to do Matcher.Run.
        var handler = NewHandler("worker@system", Roles.System);
        var requirement = new PermissionRequirement(Permissions.MatcherRun);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal("worker@system"), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeTrue("System must be granted Matcher.Run in rbac_policy.csv");
    }

    [Fact]
    public async Task Unauthenticated_Request_IsRejected()
    {
        // Negative: no current user bound → 403 regardless of the policy.
        var handler = NewHandler(currentUserEmail: null, role: null);
        var requirement = new PermissionRequirement(Permissions.AlertsReadOwn);

        var context = new AuthorizationHandlerContext(new[] { requirement }, NewPrincipal(""), resource: null);
        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeFalse("Unauthenticated requests must be rejected by the RBAC handler");
    }

    // -- helpers ------------------------------------------------------------

    private static RbacPolicyHandler NewHandler(string? currentUserEmail, string? role) =>
        new(
            new FakeCurrentUser(currentUserEmail, role),
            new StaticEnforcerBootstrap(NewEnforcer()),
            NullLogger<RbacPolicyHandler>.Instance);

    private static System.Security.Claims.ClaimsPrincipal NewPrincipal(string email) =>
        new(new System.Security.Claims.ClaimsIdentity(
            [new System.Security.Claims.Claim(System.Security.Claims.ClaimTypes.Email, email)],
            authenticationType: "Test"));

    private static IEnforcer NewEnforcer()
    {
        var modelPath = FindAuthFile("casbin_model.conf");
        var policyPath = FindAuthFile("rbac_policy.csv");
        var enforcer = new Enforcer(modelPath, policyPath);
        enforcer.AutoBuildRoleLinks = true;
        return enforcer;
    }

    private static string FindAuthFile(string fileName)
    {
        // The test assembly's bin directory mirrors the project tree; the
        // auth files are copied next to the assembly by the Infrastructure
        // csproj (None Update CopyToOutputDirectory).
        var dir = new System.IO.DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = System.IO.Path.Combine(dir.FullName, "Auth", fileName);
            if (System.IO.File.Exists(candidate)) return candidate;
            dir = dir.Parent;
        }
        throw new System.IO.FileNotFoundException($"Could not locate Auth/{fileName} from {AppContext.BaseDirectory}");
    }

    private sealed class FakeCurrentUser(string? email, string? role) : ICurrentUser
    {
        public System.Guid? Id => email is null ? null : System.Guid.NewGuid();
        public string? Email => email;
        public SonrisaNews.Domain.UserRole? Role => role is null
            ? null
            : System.Enum.TryParse<SonrisaNews.Domain.UserRole>(role, out var r) ? r : null;
        public bool IsAuthenticated => email is not null;
    }

    /// <summary>In-memory enforcer bootstrap for tests. Returns a freshly built enforcer per test (no cross-test state).</summary>
    private sealed class StaticEnforcerBootstrap(IEnforcer enforcer) : IEnforcerBootstrap
    {
        public Task<IEnforcer> GetEnforcerAsync(string? authenticationScheme = null) => Task.FromResult(enforcer);
    }
}
