{"content":"using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SonrisaNews.Infrastructure.Auth;

namespace SonrisaNews.Api.Auth;

/// <summary>
/// At API startup, after the schema is migrated, hydrate the Casbin
/// enforcer with every existing user's role. New signups go through
/// <see cref="IRoleGroupingService.EnsureGroupingAsync"/> from the auth
/// flow.
/// </summary>
public sealed class RbacHydrationHostedService(
    IServiceScopeFactory scopeFactory,
    ILogger<RbacHydrationHostedService> logger) : IHostedService
{
    public async Task StartAsync(CancellationToken ct)
    {
        try
        {
            await using var scope = await scopeFactory.CreateAsyncScope();
            var grouping = scope.ServiceProvider.GetRequiredService<IRoleGroupingService>();
            await grouping.HydrateAsync(ct);
        }
        catch (Exception ex)
        {
            // Log and re-throw: a misconfigured enforcer is a security
            // boundary failure and the API should refuse to start.
            logger.LogError(ex, "RBAC hydration failed at startup");
            throw;
        }
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
