namespace SonrisaNews.Domain.Auth;

/// <summary>
/// A role in the RBAC catalog. Roles are seeded at migration time; the
/// three MVP rows are <c>User</c>, <c>Admin</c>, and <c>System</c>. A user
/// has zero or more roles via the <c>UserRoles</c> join table; a role has
/// zero or more permissions via the <c>RolePermissions</c> join table.
/// </summary>
/// <remarks>
/// The <see cref="Name"/> column is the stable, code-time identifier (e.g.
/// <c>"Admin"</c>). The <see cref="DisplayName"/> is for the admin UI.
/// </remarks>
public class Role
{
    public Guid Id { get; set; }

    /// <summary>Stable code-time identifier. The <see cref="Roles"/> constants are the only values a code path may compare against.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Human-readable name for the admin UI.</summary>
    public string DisplayName { get; set; } = string.Empty;

    /// <summary>Free-form description; shown in the admin "roles" page.</summary>
    public string? Description { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    /// <summary>The user→role grants for this role. Navigation only — the DB is the source of truth.</summary>
    public ICollection<UserRole> UserRoles { get; set; } = [];

    /// <summary>The role→permission grants for this role. Navigation only.</summary>
    public ICollection<RolePermission> RolePermissions { get; set; } = [];
}

namespace SonrisaNews.Domain.Auth;

/// <summary>
/// A permission in the RBAC catalog. Permissions are seeded at migration
/// time; one row per constant in <see cref="Permissions"/>. A permission
/// has zero or more roles via the <c>RolePermissions</c> join table.
/// </summary>
/// <remarks>
/// The <see cref="Name"/> column is the stable, code-time identifier (e.g.
/// <c>"Alerts.Read.Own"</c>). Every <c>[Authorize(Policy = Permissions.X)]</c>
/// in a controller must have a row in this table AND a grant in
/// <c>RolePermissions</c> for at least one role; the <c>rbac-audit</c>
/// tool enforces this.
/// </remarks>
public class Permission
{
    public Guid Id { get; set; }

    /// <summary>Stable code-time identifier. Matches the <see cref="Permissions"/> constants exactly.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Human-readable description; shown in the admin "permissions" page.</summary>
    public string? Description { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    /// <summary>The role→permission grants for this permission. Navigation only.</summary>
    public ICollection<RolePermission> RolePermissions { get; set; } = [];
}

namespace SonrisaNews.Domain.Auth;

/// <summary>
/// Join row: a user has a role. Composite key on
/// <c>(UserId, RoleId)</c> — a user cannot have the same role twice.
/// </summary>
/// <remarks>
/// A future wave that adds role-scoping (e.g. <c>per-team admin</c>) can
/// extend this join with a <c>Scope</c> column; the matcher in
/// <see cref="SonrisaNews.Infrastructure.Auth.RbacPolicyHandler"/> would
/// need to look at it.
/// </remarks>
public class UserRole
{
    public Guid UserId { get; set; }
    public Guid RoleId { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    /// <summary>The user side of the join. Navigation only.</summary>
    public User? User { get; set; }

    /// <summary>The role side of the join. Navigation only.</summary>
    public Role? Role { get; set; }
}

namespace SonrisaNews.Domain.Auth;

/// <summary>
/// Join row: a role has a permission. Composite key on
/// <c>(RoleId, PermissionId)</c> — a role cannot have the same permission twice.
/// </summary>
public class RolePermission
{
    public Guid RoleId { get; set; }
    public Guid PermissionId { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    /// <summary>The role side of the join. Navigation only.</summary>
    public Role? Role { get; set; }

    /// <summary>The permission side of the join. Navigation only.</summary>
    public Permission? Permission { get; set; }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
